template <typename MaybeConstUserType>
struct Serializer<::chromeos::machine_learning::mojom::TextEntityDataDataView, MaybeConstUserType> {
  using UserType = typename std::remove_const<MaybeConstUserType>::type;
  using Traits = UnionTraits<::chromeos::machine_learning::mojom::TextEntityDataDataView, UserType>;

  static void Serialize(MaybeConstUserType& input,
                        MessageFragment<::chromeos::machine_learning::mojom::internal::TextEntityData_Data>& fragment,
                        bool inlined) {
    if (CallIsNullIfExists<Traits>(input)) {
       if (inlined)
        fragment->set_null();
      return;
    }

    if (!inlined)
      fragment.Allocate();

    // TODO(azani): Handle unknown and objects.
    // Set the not-null flag.
    fragment->size = kUnionDataSize;
    fragment->tag = Traits::GetTag(input);
    switch (fragment->tag) {
      case ::chromeos::machine_learning::mojom::TextEntityDataDataView::Tag::NUMERIC_VALUE: {
        decltype(Traits::numeric_value(input))
            in_numeric_value = Traits::numeric_value(input);
        fragment->data.f_numeric_value = in_numeric_value;
        break;
      }
      case ::chromeos::machine_learning::mojom::TextEntityDataDataView::Tag::STRING_VALUE: {
        decltype(Traits::string_value(input))
            in_string_value = Traits::string_value(input);
        mojo::internal::MessageFragment<
            typename decltype(fragment->data.f_string_value)::BaseType>
            value_fragment(fragment.message());
        mojo::internal::Serialize<mojo::StringDataView>(
            in_string_value, value_fragment);
        MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
            value_fragment.is_null(),
            mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
            "null string_value in TextEntityData union");
        fragment->data.f_string_value.Set(
            value_fragment.is_null() ? nullptr : value_fragment.data());
        break;
      }
    }
  }

  static bool Deserialize(::chromeos::machine_learning::mojom::internal::TextEntityData_Data* input,
                          UserType* output,
                          Message* message) {
    if (!input || input->is_null())
      return CallSetToNullIfExists<Traits>(output);

    ::chromeos::machine_learning::mojom::TextEntityDataDataView data_view(input, message);
    return Traits::Read(data_view, output);
  }
};

